import random


def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    # Pull out compact views of the match so far.
    # Because noise is zero, executed actions equal intended actions.
    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    my_d = 0
    for a in op:
        if a == 'C':
            op_c += 1
    for a in me:
        if a == 'D':
            my_d += 1
    op_d = n - op_c

    last_me = me[-1]
    last_op = op[-1]

    # -------- Endgame exploitation of pure or near-pure cooperators --------
    # Against an opponent that has essentially never defected, defecting on the
    # last few rounds is strictly better than cooperating (5 instead of 3),
    # and there is no future punishment to fear.
    if op_d <= 1:
        if n >= 96:
            # Take the defection payoff on the final rounds.
            return 'D'
        # Keep the relationship healthy until the very end, with a rare
        # probe so we are not purely predictable.
        if n < 90 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # -------- Strongly cooperative opponent --------
    # Opponent cooperates almost always but has defected a few times.
    # Stay mostly cooperative, punish the most recent defection, and lean
    # harder into exploitation late.
    if op_c >= n - max(2, n // 12):
        if last_op == 'D':
            # Immediate proportional retaliation, then back to cooperation.
            return 'D'
        if n >= 92:
            # Late-game grab against a benign opponent.
            if rng.random() < 0.7:
                return 'D'
        if n < 80 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # -------- Mostly defective opponent --------
    # Avoid being farmed. Probe a bit to detect a possible change, but do not
    # hand out free cooperation too generously.
    if op_c * 2 <= n:
        # Break mutual-defection runs occasionally to reset the relationship.
        if last_me == 'D' and last_op == 'D':
            if n < 90 and rng.random() < 0.25:
                return 'C'
            return 'D'
        if last_op == 'D':
            # Punish a fresh defection against our cooperation.
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        # Opponent cooperated while we were punishing: reward it.
        return 'C'

    # -------- General adaptive regime --------
    # Look at a recent window to detect runs of defection and cooperation.
    window = history[-10:] if n >= 10 else history
    w_len = len(window)
    rec_op_d = 0
    rec_op_c = 0
    rec_me_d = 0
    for a, b in window:
        if b == 'D':
            rec_op_d += 1
        else:
            rec_op_c += 1
        if a == 'D':
            rec_me_d += 1

    # Sustained defection by opponent: match it, but allow a reset attempt.
    if rec_op_d * 2 > w_len:
        if last_op == 'D' and last_me == 'D' and n < 95:
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    # Mutual defection loop: cooperate to try to re-establish mutual CC.
    if last_me == 'D' and last_op == 'D':
        if rng.random() < 0.6:
            return 'C'
        return 'D'

    # If we defected while opponent has been cooperating, repair by cooperating
    # (unless we are deep in the endgame where further exploitation pays).
    if last_me == 'D' and last_op == 'C':
        if n >= 90:
            # Near the end, keep exploiting a forgiving opponent.
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Opponent defected against our cooperation: retaliate, but forgive if
    # their longer history has been reasonably cooperative.
    if last_op == 'D':
        if rec_op_c >= 4 and op_c * 2 >= n:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent cooperated last. Reward cooperation; probe occasionally and
    # exploit more near the end against a sufficiently lenient opponent.
    if n >= 90 and op_c * 3 >= n * 2:
        if rng.random() < 0.4:
            return 'D'
    if n < 85 and rng.random() < 0.02:
        return 'D'
    return 'C'
